class const_iterator {
public:
    using iterator_category = std::forward_iterator_tag;
    using value_type = T;
    using difference_type = std::ptrdiff_t;
    using reference = const T&;
    using pointer = const T*;

    const_iterator() = default;
    explicit const_iterator(const binary_tree* root) { push_left_spine(root); }

    reference operator*() const { return stack_.top()->data_; }
    pointer operator->() const { return &stack_.top()->data_; }

    const_iterator& operator++() {
        const binary_tree* node = stack_.top();
        stack_.pop();
        push_left_spine(node->right_.get());
        return *this;
    }
    const_iterator operator++(int) { const_iterator tmp = *this; ++*this; return tmp; }

    bool operator==(const const_iterator& other) const { return stack_ == other.stack_; }
    bool operator!=(const const_iterator& other) const { return !(*this == other); }

private:
    void push_left_spine(const binary_tree* node) {
        while (node) { stack_.push(node); node = node->left_.get(); }
    }
    std::stack<const binary_tree*> stack_;
};
```

