#include <cstddef>
#include <iterator>
#include <memory>
#include <stack>

namespace binary_search_tree {

template<typename T>
class binary_tree {
public:
    explicit binary_tree(const T& data_value) : data_(data_value) {}

    void insert(const T& value) {
        binary_tree* node = this;
        while (true) {
            if (value <= node->data_) {
                if (!node->left_) {
                    node->left_.reset(new binary_tree(value));
                    return;
                }
                node = node->left_.get();
            } else {
                if (!node->right_) {
                    node->right_.reset(new binary_tree(value));
                    return;
                }
                node = node->right_.get();
            }
        }
    }

    const T& data() const { return data_; }

    const std::unique_ptr<binary_tree>& left() const { return left_; }

    const std::unique_ptr<binary_tree>& right() const { return right_; }

    class const_iterator {
    public:
        using iterator_category = std::forward_iterator_tag;
        using value_type = T;
        using difference_type = std::ptrdiff_t;
        using reference = const T&;
        using pointer = const T*;

        const_iterator() = default;

        explicit const_iterator(const binary_tree* root) { push_left_spine(root); }

        reference operator*() const { return stack_.top()->data_; }
        pointer operator->() const { return &stack_.top()->data_; }

        const_iterator& operator++() {
            const binary_tree* node = stack_.top();
            stack_.pop();
            push_left_spine(node->right_.get());
            return *this;
        }

        const_iterator operator++(int) {
            const_iterator previous(*this);
            ++(*this);
            return previous;
        }

        bool operator==(const const_iterator& other) const { return stack_ == other.stack_; }
        bool operator!=(const const_iterator& other) const { return !(*this == other); }

    private:
        void push_left_spine(const binary_tree* node) {
            while (node != nullptr) {
                stack_.push(node);
                node = node->left_.get();
            }
        }

        std::stack<const binary_tree*> stack_;
    };

    const_iterator begin() const { return const_iterator(this); }

    const_iterator end() const { return const_iterator(); }

private:
    T data_;
    std::unique_ptr<binary_tree> left_;
    std::unique_ptr<binary_tree> right_;
};

}  // namespace binary_search_tree

